import{z as n,x as d,o as E,c as B,q as r,j as i,D as t,d as l,s,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"机台价格与折旧","description":"","frontmatter":{"title":"机台价格与折旧","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tool-price-depreciation.md","filePath":"litho/tool-price-depreciation.md","lastUpdated":1791063341000}'),A={name:"litho/tool-price-depreciation.md"};function h(c,a,m,D,u,f){const o=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=r('<h1 id="机台价格与折旧" tabindex="-1">机台价格与折旧 <a class="header-anchor" href="#机台价格与折旧" aria-label="Permalink to &quot;机台价格与折旧&quot;">​</a></h1><div class="epigraph"><p>扫描机的小时成本是买价按年折旧再除以有效 wph；EUV 与高 NA 把分子抬高，剂量把分母压低。</p><footer>—— 对照 ASML FY2024：净销售 €28.3B；EUV 系统销售 €8.3B / 44 台（含 High-NA）；DUV €12.8B / 374 台；Installed Base €6.5B。年报给销量与销售额，不给可抄的价目表</footer></div><p><a href="/litho/euv-vs-multipattern-cost-crossover">上一课</a>用模块成本比较路径。缺口是模块里最大的资本项。本课钉机台价格与折旧。折旧如何在厂级变成瓶颈机台数量，留给<a href="/litho/capacity-planning-bottleneck">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>光刻机台（尤其 EUV、高 NA）是晶圆厂最贵的单机之一。会计上折旧年限（常见五到七年量级的产业讨论，非本课税法意见）把买价摊成年度成本，再按可用小时与 wph 摊到晶圆。维护、光源耗材、服务合同是现金，不一定走同一折旧科目，但进小时成本。浸没机单价低、wph 高，多重次数把有效层成本拉回。</p><p>缺口是<strong>资本回收</strong>，不是光学。ASML 年报给的是销量与销售额：2024 年 EUV 系统 €8.3B、确认收入 44 台（NXE 与 EXE），DUV €12.8B、374 台。这只是平均确认收入量级，混有机型与升级，<strong>不是</strong>目录价。服务与升级走 Installed Base（2024 年 €6.5B），与折旧并列进小时成本。</p><h3 id="有效-wph" tabindex="-1">有效 wph <a class="header-anchor" href="#有效-wph" aria-label="Permalink to &quot;有效 wph&quot;">​</a></h3><p>可用性、setup、剂量、pellicle、计量插入，把铭牌 wph 打成有效 wph。折旧分母是有效，不是铭牌。</p><p><span class="marginnote">高 NA 半场可能让大 die 的有效场数下降，分母再变。经济课与拼接课必须一起读。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>小时成本 ≈ (折旧 + 服务 + 耗材) / 有效小时。层成本再除有效 wph 乘过机次数。产能规划用同一套分母。与掩模：写模机也是折旧对象，进掩模摊销。</p><p><span class="marginnote">折旧翻译成大白话：把一次付清的大买价摊成逐年逐小时的「房租」。机器哪怕停着不动，这笔成本也按会计规则每天落下——所以「停一天亏一天」对贵机台不是修辞，是账面事实。</span></p><p><span class="marginnote">代个数感受量级：按文中 ASML 披露口径，EUV 系统 €8.3B 对应 44 台，平均确认收入约 €1.9 亿一台（混机型均值，不是标价）；按七年摊，一年约 €2700 万，再摊到每年数千有效小时上，每小时就是数千欧元的量级。</span></p>',13)),(E(),i(p,null,{default:t(()=>[s(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NP%5B%22%E9%93%AD%E7%89%8C%20wph%22%5D%20--%3E%20EW%5B%22%E6%9C%89%E6%95%88%20wph%22%5D%0A%20%20AV%5B%22%E5%8F%AF%E7%94%A8%E6%80%A7%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20EW%0A%20%20SU%5B%22setup%20%E4%B8%8E%E6%8D%A2%E6%89%B9%22%5D%20--%3E%20EW%0A%20%20DOSE%5B%22%E5%89%82%E9%87%8F%E8%B6%85%E9%A2%84%E7%AE%97%22%5D%20--%3E%20EW%0A%20%20PEL%5B%22pellicle%20%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20EW%0A%20%20MET%5B%22%E8%AE%A1%E9%87%8F%E6%8F%92%E5%85%A5%22%5D%20--%3E%20EW%0A%20%20DEP%5B%22%E5%B9%B4%E6%8A%98%E6%97%A7%20%2B%20%E6%9C%8D%E5%8A%A1%20%2B%20%E8%80%97%E6%9D%90%22%5D%20--%3E%20HR%5B%22%E5%B0%8F%E6%97%B6%E6%88%90%E6%9C%AC%22%5D%0A%20%20EW%20--%3E%20HR%0A%20%20HR%20--%3E%20LC%5B%22%E5%B1%82%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"固定成本高的机台必须高利用率，否则小时爆炸——这会压迫排产把非临界层塞进浸没，把 EUV 留给交叉后的层。利用率与混跑策略因此是财务约束，不只是工程偏好。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：算层成本用铭牌 wph。真实分母要扣掉可用性、setup、剂量与计量插入，铭牌打折扣是常态——分母一缩水，每小时成本立刻上浮，单机经济性比按买价的直觉差一截。")],-1)),(E(),i(p,null,{default:t(()=>[s(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRICE%5B%22%E4%B9%B0%E4%BB%B7%22%5D%20--%3E%20DEP%5B%22%E5%B9%B4%E6%8A%98%E6%97%A7%22%5D%0A%20%20DEP%20--%3E%20HR%5B%22%E5%B0%8F%E6%97%B6%E6%88%90%E6%9C%AC%22%5D%0A%20%20AVAIL%5B%22%E5%8F%AF%E7%94%A8%E5%B0%8F%E6%97%B6%20%C3%97%20%E6%9C%89%E6%95%88%20wph%22%5D%20--%3E%20HR%0A%20%20HR%20--%3E%20LAYER%5B%22%E5%B1%82%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供投资建议，不给具体标价。折旧年限因公司而异。机台价格不含厂房。</p><p>后课默认：小时成本由折旧与有效 wph 决定；下一课用它来数需要几台、瓶颈在哪。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>层资本成本来自折旧除以有效 wph，不是铭牌。</li><li>高单价机必须高利用率，从而塑造混跑。</li><li>不把传闻标价写进账。</li><li>出处：ASML Q4/FY 2024 新闻稿与 IR 演示（2025-01-29）；半导体设备折旧的产业通称。不把 €8.3B/44 写成标价。</li></ul>',5))])}const P=n(A,[["render",h]]);export{C as __pageData,P as default};
